UPDATE biz_practical_attachment
SET preview_status = 'converting',
    preview_last_retry_time = #{claimedAt},
    update_time = #{claimedAt}
WHERE attachment_id = #{attachmentId}
  AND preview_status = 'pending'

UPDATE biz_practical_attachment
SET normalized_status = 'converting',
    normalized_last_retry_time = #{claimedAt},
    update_time = #{claimedAt}
WHERE attachment_id = #{attachmentId}
  AND normalized_status = 'pending'

mapper.select:
SELECT * FROM biz_practical_attachment
WHERE sha256 = #{sha256}
  AND renderer_version = #{rendererVersion}
  AND normalized_status = 'success'
  AND normalized_pages_json IS NOT NULL
  AND attachment_id != #{excludeAttachmentId}
ORDER BY attachment_id DESC
LIMIT 1

